const Y_TICKS = [['1,000', 164.07], ['100', 197.096], ['10', 230.125], ['1', 263.15], ['0.1', 296.18]];
const BD_OBS = [['High expression:', ' CESC, OV, ESCA, CHOL, BRCA, consistent with TACSTD2 (Trop-2) as a known epithelial cancer target'],
  ['Low expression:', ' GBM and other non-epithelial types, mostly near 0 TPM with occasional outliers'],
  ['Wide dynamic range:', ' near-zero to over 3,000 TPM (log-scaled y axis)']];

function Piece({ caret }) {
  const { T, CUES } = useComposition();
  const I = CUES['Input'], S = CUES['Submit'], P = CUES['Processing'], RS = CUES['Result'], CH = CUES['Chart'], OUT = CUES['Outro'];
  const scroll = MOTION.move(T, -95, [{ at: P, dur: 1.0, to: 8 }, { at: RS, dur: 1.0, to: 222 }, { at: CH, dur: 1.0, to: 462 }]);
  // The loader only shows below the newest block once everything above it has finished revealing.
  const L = loaderState(T, S + 0.95, 155, [{ at: P + 0.15, to: 343, back: P + 2.0 }, { at: RS + 0.15, to: 553, back: RS + 1.8 }], CH);
  const running = T < CH ? 0.75 + 0.25 * Math.cos((T - P) * Math.PI * 1.25) : 1;
  const steps = [P + 0.6, P + 1.1, P + 1.6];
  const rs = (d, dy = 3) => MOTION.enter(T, RS + d, 0.32, dy);
  const ch = (d, dy = 3) => MOTION.enter(T, CH + d, 0.35, dy);
  const fade = (at, d = 0.3) => Easing.easeOutCubic(prog(T, at, d));
  const outro = 1 - Easing.easeInOutCubic(prog(T, OUT + 0.05, 0.7));
  return (
    <div data-screen-label={`t=${Math.floor(T)}s`} style={{ position: 'absolute', left: 0, top: 0, width: 729, height: 478,
      transform: 'scale(2)', transformOrigin: '0 0', fontFamily: FONT, color: INK }}>
      <div style={{ position: 'absolute', inset: 0, background: BG, borderRadius: 20, overflow: 'hidden' }}>
        <div style={{ position: 'absolute', inset: 0, opacity: outro }}>
        <div style={{ position: 'absolute', left: 0, top: 0, width: 729, height: 900, transform: `translateY(${(-scroll).toFixed(2)}px)` }}>
          <Bubble top={0} left={111.5} w={563} h={48} tw={545} label="EDWARD" text={REQ1} st={MOTION.enter(T, S + 0.55, 0.38, 10)} />
          <Loader frame={L.frame} style={{ top: L.y, opacity: L.op }} />
          <AgentHeader top={147} st={MOTION.enter(T, P + 0.2, 0.32, 6)} />
          <div style={{ position: 'absolute', left: 54.5, top: 185, width: 620, height: 126, background: '#fff', borderRadius: 8, boxShadow: CARD_SHADOW, ...MOTION.enter(T, P + 0.3, 0.32, 6) }}>
            <Ln x={12} b={21.2} s={12} w={600}>Thinking...</Ln>
            <Ln rr={12.6} b={21.6} s={12} w={600} style={{ opacity: running }}>Running</Ln>
            <div style={{ position: 'absolute', left: 12, top: 32, width: 596, height: 84, background: INNER, borderRadius: 8 }}>
              {[['Tool call', "search_in_descriptor('gene expression TPM sample')"], ['Tool call', "search_in_descriptor('cancer type tumor type project')"], ['Output', 'dx_tumor_type · dx_cancer_type_detailed']].map((r, i) => (
                <div key={i} style={{ position: 'absolute', inset: 0, ...MOTION.enter(T, steps[i], 0.3, 4) }}>
                  <Ln x={12} b={23 + i * 24} s={14} w={600}>{r[0]}</Ln>
                  <Ln x={112.5} b={23 + i * 24} s={14} w={400}>{r[1]}</Ln>
                </div>
              ))}
            </div>
          </div>

          <div style={{ position: 'absolute', left: 54.5, top: 325, width: 620, height: 196, background: '#fff', borderRadius: 8, ...rs(0.2, 6) }}>
            <div style={rs(0.4)}><Ln x={12} b={24} s={12} w={500}><b style={{ fontWeight: 600 }}>TACSTD2</b><span style={{ marginLeft: 5 }}>·10,288 measurements · all TCGA cancer types</span></Ln></div>
            <div style={{ position: 'absolute', left: 12, top: 46, width: 596, height: 140, background: INNER, borderRadius: 8, ...rs(0.5, 6) }}>
              <div style={rs(0.62)}><Ln x={12} b={22.8} s={14} w={600}>Key observations:</Ln></div>
              <div style={{ position: 'absolute', left: 21, top: 32.9, width: 563, fontSize: 14, lineHeight: '20px', display: 'flex', flexDirection: 'column' }}>
                {BD_OBS.map((o, i) => (
                  <div key={i} style={{ display: 'flex', ...rs(0.75 + i * 0.12) }}>
                    <span style={{ width: 12, flex: 'none' }}>•</span>
                    <span style={{ flex: 1, minWidth: 0 }}><b style={{ fontWeight: 700 }}>{o[0]}</b>{o[1]}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div style={{ position: 'absolute', left: 54.5, top: 535, width: 620, height: 292, ...ch(0.25, 6) }}>
            <div style={{ position: 'absolute', left: 0, right: 0, top: 30, bottom: 0, borderRadius: 10, ...flowStrip(T, CH + 0.25) }} />
            <div style={{ position: 'absolute', left: 0, right: 0, top: 0, height: 290, background: '#fff', borderRadius: 10 }}>
              <div style={ch(0.4)}><Ln x={24.5} b={35} s={16} w={700}>TACSTD2 Expression by Cancer Type</Ln></div>
              <div style={ch(0.5)}><Ln x={24.9} b={53.8} s={10} w={400}>ENSG00000184292 (Trop-2), TCGA pan-cancer</Ln></div>
              <svg width="620" height="290" viewBox="54.5 73 620 290" style={{ position: 'absolute', left: 0, top: 0, overflow: 'visible', fontFamily: FONT }}>
                <defs>
                  {STRIP.map((c, j) => {
                    const p = spring(prog(T, CH + 0.75 + j * 0.06, 0.95), 0.9, 8);
                    return <clipPath key={j} id={`bdcol${j}`}><rect x={c.x - 1} y={312 - 180 * p} width="15.2" height={180 * p} /></clipPath>;
                  })}
                </defs>
                <g style={{ opacity: fade(CH + 0.5) }}>
                  <path d={ICON_DL} fill={INK} transform="translate(8 28)" />
                  <path d={ICON_MORE} fill={INK} transform="translate(0 28)" />
                </g>
                {Y_TICKS.map((t, i) => (
                  <g key={i} style={{ opacity: fade(CH + 0.55 + i * 0.03) }}>
                    <line x1="109.373" y1={t[1]} x2="662.5" y2={t[1]} stroke="#AEAEB2" strokeWidth="0.5" strokeDasharray="1 2" />
                    <text x="99.3" y={t[1] + 2.2} textAnchor="end" fill={INK} fontSize="6">{t[0]}</text>
                  </g>
                ))}
                <text transform="translate(74.4 225.3) rotate(-90)" textAnchor="middle" fill={INK} fontSize="6.5" fontWeight="700" style={{ opacity: fade(CH + 0.6) }}>Expression (TPM)</text>
                {STRIP.map((c, j) => (
                  <g key={j} style={{ opacity: fade(CH + 0.75 + j * 0.06, 0.45) }}>
                    <g clipPath={`url(#bdcol${j})`} fill="#5E5EA8">
                      {c.ys.map((y, k) => <rect key={k} x={c.x} y={y} width="13.2" height="0.66" />)}
                    </g>
                    <text x={c.x + 6.6} y="324.3" textAnchor="middle" fill={INK} fontSize="5" fontWeight={j < 5 ? 700 : 400}>{CANCERS[j]}</text>
                  </g>
                ))}
              </svg>
              <div style={{ opacity: fade(CH + 2.95, 0.4) }}><Ln x={24.4} b={267.6} s={7.5} w={700}>10,288 expression measurements</Ln></div>
              <div style={{ opacity: fade(CH + 3.05, 0.4) }}><Ln x={24.7} b={275.9} s={6.5} w={400}>Highest medians in epithelial tumors (CESC, OV, ESCA, CHOL, BRCA). Near zero in GBM and other non-epithelial types.</Ln></div>
              <div style={{ opacity: fade(CH + 3.1, 0.4) }}><Ln rr={12.4} b={275.9} s={6.5} w={400} c={MUTED}>log scale, sorted by median</Ln></div>
            </div>
          </div>
        </div>
        <Composer T={T} e={I + 0.05} S={S} label="ASK ODA IN NATURAL LANGUAGE" top={202} req={REQ1} times={TYPE1} caret={caret} accent={GREEN} tw={425} />
        </div>
        <div style={{ position: 'absolute', left: 1, top: 347, width: 728, height: 131, background: `linear-gradient(180deg, rgba(240,250,224,0) 0%, ${BG} 100%)`, pointerEvents: 'none' }} />
      </div>
    </div>
  );
}

function ODABDAnimation() {
  const [t, setTweak] = useTweaks(window.TWEAK_DEFAULTS);
  return (
    <React.Fragment>
      <CompositionStage width={1458} height={956} scenes={window.OM_SCENES} playback={window.OM_PLAYBACK} bg={t.corner}>
        <Piece caret={t.caret} />
      </CompositionStage>
      <TweaksPanel>
        <TweakSection label="Playback" />
        <TweakToggle label="Motion editor" value={t.motionEditor} onChange={(v) => setTweak('motionEditor', v)} />
        <TweakSection label="Input" />
        <TweakRadio label="Caret" value={t.caret} options={['inline', 'accent bar']} onChange={(v) => setTweak('caret', v)} />
        <TweakSection label="Video" />
        <TweakColor label="Corner fill" value={t.corner} options={['#FFFFFF', '#F0FAE0', '#000000']} onChange={(v) => setTweak('corner', v)} />
      </TweaksPanel>
    </React.Fragment>
  );
}
window.ODABDAnimation = ODABDAnimation;
